import runpy
import unittest


def rodar():
    """Roda solucao.py do zero e devolve o que ele definiu."""
    return runpy.run_path("solucao.py")


class TestAListaQueNaoMuda(unittest.TestCase):
    def test_par_de_notas_guarda_o_primeiro_valor(self):
        """par_de_notas guarda o primeiro valor no lugar zero"""
        self.assertEqual(rodar()["par_de_notas"](7, 9)[0], 7)

    def test_par_de_notas_guarda_o_segundo_valor(self):
        """par_de_notas guarda o segundo valor no lugar um"""
        self.assertEqual(rodar()["par_de_notas"](7, 9)[1], 9)

    def test_par_de_notas_na_ordem_contraria(self):
        """par_de_notas devolve a ordem contraria quando recebe a ordem contraria"""
        self.assertEqual(rodar()["par_de_notas"](9, 7)[0], 9)
        self.assertEqual(rodar()["par_de_notas"](9, 7)[1], 7)
